const Icons={AlertTriangle, ArrowRight, ArrowUpRight, Bell, Boxes, Cable, CalendarClock, ChartNoAxesCombined, Check, CheckCheck, ChevronRight, ChevronsUpDown, Circle, CircleAlert, ClipboardCheck, Clock3, Coins, Download, Factory, FileChartColumn, FileCheck2, Flame, GitCompareArrows, Globe2, History, Inbox, Info, Layers, LayoutDashboard, Lightbulb, LoaderCircle, Menu, Network, Package, PanelsTopLeft, Plus, Printer, RefreshCw, Route, Scale, ScanLine, Search, Settings2, ShieldCheck, ShoppingBag, ShoppingCart, Sparkles, Tags, TrendingDown, Truck, Undo2, UploadCloud, Users, Wallet, Warehouse, Workflow, X};
